for score in [95, 85, 72, 64, 40]:
    if score >= 90:
        grade = "A"
    elif score >= 80:  # only reached when score < 90
        grade = "B"
    elif score >= 70:
        grade = "C"
    elif score >= 60:
        grade = "D"
    else:
        grade = "F"

    if grade != "F":  # a decision inside the loop's block
        message = "pass with honors" if grade == "A" else "pass"
    else:
        message = "try again"
    print(f"{score}: {grade} ({message})")

# The same idea in the wrong order: the first true branch wins
score = 95
if score >= 60:
    grade = "D"
elif score >= 90:
    grade = "A"
else:
    grade = "F"
print("wrong order gives 95 a", grade)

def rectangle_area(width, height):
    return width * height


def grade(score):
    if score >= 90:
        return "A"  # return ends the function right here
    if score >= 80:
        return "B"
    return "C or below"


def print_area(width, height):
    print("area is", width * height)  # prints, but returns nothing


def min_max(numbers):
    return min(numbers), max(numbers)  # two values, returned as a tuple


area = rectangle_area(3, 4)
print("area:", area)
print("two rooms:", rectangle_area(3, 4) + rectangle_area(2, 5))
print(grade(95), grade(85), grade(50))

result = print_area(3, 4)
print("print_area returned:", result)

low, high = min_max([7, 2, 9, 4])
print("low", low, "high", high)
